  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Sky
  brush.fill("#87CEEB"); // Sky blue
  brush.fillBleed(0.5);
  brush.beginShape();
  brush.vertex(0, 0); // Top left corner
  brush.vertex(400, 0); // Top right corner
  brush.vertex(400, 400); // Bottom right corner
  brush.vertex(0, 400); // Bottom left corner
  brush.endShape(true);

  // Green hills
  brush.fill("#006400"); // Green hill color
  brush.fillBleed(0.3);
  brush.beginShape();
  brush.vertex(0, 200); // Top left hill corner
  brush.vertex(400, 200); // Top right hill corner
  brush.vertex(400, 300); // Bottom right hill corner
  brush.vertex(0, 300); // Bottom left hill corner
  brush.endShape(true);

  // Sun
  brush.fill("#FFD700"); // Yellow sun color
  brush.fillBleed(0.8);
  brush.beginShape();
  brush.vertex(200, 100); // Sun position
  brush.vertex(220, 50); // Sun position
  brush.vertex(240, 50); // Sun position
  brush.vertex(220, 100); // Sun position
  brush.endShape(true);
}
