  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Sky
  brush.fill("#87CEEB"); // Sky blue
  brush.fillBleed(0.5);
  brush.beginShape();
  brush.vertex(0, 0); // Top left
  brush.vertex(400, 0); // Top right
  brush.vertex(400, 400); // Bottom right
  brush.vertex(0, 400); // Bottom left
  brush.endShape(true);

  // Green hills
  brush.fill("#006400"); // Green
  brush.fillBleed(0.3);
  brush.beginShape();
  brush.vertex(0, 100); // Top left hill
  brush.vertex(400, 100); // Top right hill
  brush.vertex(400, 200); // Bottom right hill
  brush.vertex(0, 200); // Bottom left hill
  brush.endShape(true);

  // Sun
  brush.fill("#FFD700"); // Yellow
  brush.fillBleed(0.8);
  brush.beginShape();
  brush.vertex(200, 50); // Sun position
  brush.vertex(220, 30); // Top of sun
  brush.vertex(250, 30); // Top of sun
  brush.vertex(280, 30); // Top of sun
  brush.vertex(300, 30); // Top of sun
  brush.vertex(320, 30); // Top of sun
  brush.vertex(340, 30); // Top of sun
  brush.vertex(360, 30); // Top of sun
  brush.vertex(380, 30); // Top of sun
  brush.vertex(400, 50); // Bottom of sun
  brush.endShape(true);
}

